import { BooleanColumn, StringColumn } from '@servicenow/sdk/core'
import { ActionDefinition, FlowArray } from '@servicenow/sdk/automation'

export const fl_action_flow_array = ActionDefinition({
    $id: Now.ID['action-flow-array'],
    name: 'fl-action-flow-array',
    annotation: 'Test action with FlowArray',
    description: 'Demonstrates FlowArray usage with Column elements',
    category: 'Testing',
    inputs: {
        tags: FlowArray({
            elementType: StringColumn({
                label: 'Tag',
                maxLength: 50,
                default: 'tag',
                hint: 'Enter the tag',
            }),
            label: 'Tags',
            hint: 'Enter the tags for children',
            maxRows: 10,
            childName: 'tag_child0',
        }),
    },
    outputs: {
        success: BooleanColumn({
            label: 'Success',
            mandatory: true,
        }),
        errors: FlowArray({
            elementType: StringColumn({
                label: 'Error Message',
            }),
            label: 'Errors',
            childName: 'error_child0',
        }),
    },
})
